INSERT INTO `golfer` (`id`, `compid`, `firstname`, `lastname`, `nickname`, `description`, `createddate`, `admin`, `yearid`, `avatar`, `handicap`, `golflink`) VALUES
(1, 0, 'Jules', 'Stevenson', 'Pussy', 'Pussy Forest', '2013-07-05 11:58:08', 1, 5, 'img/avatar/pussy.png', NULL, ''),
(2, 0, 'Richo', 'Richardson', 'Moley', '<p class="lead">It doesn`t matter how early it might be, "The Mole" is always up for a cheeky 9 or 18. </p>\r\n\r\n<p>His inconsistent ball flight makes "Moley" ever so unpredictable on the course with a penchant for the worm burner AKA the mole raper. Even when he does get them in the air, his shots seem to skid on first bounce like Danny MacAskill on a BMX and double there distance on the ground. \r\n</p><p>\r\nThe man with the chrome dome doesn`t mind an accessory demonstrated by the loudmouth yuk pants and his GPS gadgets - "Moley" is always looking for an edge. After leading early in the 2012 event only to forfeit after a heavy night on the booze and being second place for most of 2013 to then finish second last there are serious question marks over whether "The Mole Raper" can go the distance. He`s hit the Jazzercise circuit hard in an attempt to reverse the trend of late round fade outs.</p>\r\n\r\n<blockquote class="right">"Sportsmanship for me is when a guy walks off the field and you really can`t tell whether he won or lost, when he carries himself with pride either way." <cite>- Moley</cite></blockquote>\r\n\r\n<p><b>Strength:</b> Short Game His work with the lobby and chipper tend to make up for an inconsistent long game.</p>\r\n\r\n<p><b>Weakness:</b> Sand - Bunkers are not his friend - especially those with trees or shrubs in them!</p>', '2013-07-05 11:58:47', 1, 5, 'img/avatar/mole.png', NULL, ''),
(3, 0, 'Nic', 'Luiz', 'Dolphin', 'Likes to dive', '2013-07-16 10:58:19', 0, 5, 'img/avatar/dolphin.png', NULL, ''),
(4, 0, 'Adam', 'Smith', 'Purple', 'Headed womb broom', '2013-07-16 10:58:19', 0, 5, 'img/avatar/purplw.png', NULL, ''),
(5, 0, 'Mark', 'Smith', 'Rimmer', 'Likes to rim the ringer', '2013-07-16 10:58:19', 0, 5, 'img/avatar/rimjob.png', NULL, ''),
(6, 0, 'Andrew', 'Dorian', 'Doz', 'The Burger', '2013-07-16 10:58:19', 0, 5, 'img/avatar/hungry.png', NULL, ''),
(7, 0, '', '', '', '', '2013-07-16 10:58:19', 0, 5, '', NULL, ''),
(8, 0, '', '', '', '', '2013-07-16 10:58:19', 0, 5, '', NULL, ''),
(9, 0, '', '', '', '', '2013-07-16 10:58:19', 0, 5, '', NULL, ''),
(10, 1, 'Julian', 'Stevenson', 'Pussy', 'A well planned build up to the main competition resulted in Moley being awarded a generous handicap for the main event. \r\n\r\nFollowing a par 3, double point powerplay during round 2, Pussy built up an unassailable lead going into the final day.', '2013-08-11 13:00:54', 0, NULL, NULL, NULL, ''),
(11, 1, 'Paul', 'Richardson', 'Moley', 'A solid performance from the tour chairman led to a respectable placing on the final day.', '2013-08-11 13:00:54', 0, NULL, NULL, NULL, ''),
(12, 1, 'Adam', 'Smith', 'Purple', 'The Warrior and 2013 tournament organiser', '2013-08-11 13:04:09', 0, NULL, NULL, NULL, ''),
(13, 1, 'Nic', 'Luiz', 'Dolphin', 'The smoking dolphin', '2013-08-11 13:04:09', 0, NULL, NULL, NULL, ''),
(14, 2, 'Richo', 'RIchardson', 'Moley', 'It doesn`t matter how early it might be, "The Mole" is always up for a cheeky 9 or 18. His inconsistent ball flight makes "Moley" ever so unpredictable on the course with a penchant for the worm burner AKA the mole raper. Even when he does get them in the air, his shots seem to skid on first bounce like Danny MacAskill on a BMX  and double there distance on the ground.  \r\n\r\nThe man with the chrome dome doesn`t mind an accessory demonstrated by the loudmouth yuk pants and his GPS gadgets - "Moley" is always looking for an edge. After leading early in the 2012 event only to forfeit after a heavy night on the booze and being second place for most of 2013 to then finish second last there are serious question marks over whether "The Mole Raper" can go the distance. He`s hit the Jazzercise circuit hard in an attempt to reverse the trend of late round fade outs.\r\n\r\nStrength: Short Game  His work with the lobby and chipper tend to make up for an inconsistent long game.\r\n\r\nWeakness: Sand - Bunkers are not his friend - especially those with trees or shrubs in them!', '2013-08-11 13:41:43', 0, NULL, 'img/avatar/mole.jpg', NULL, ''),
(15, 2, 'Jules', 'Stevenson', 'Pussy', 'The antipodal version of the great Tiger Woods, Pussy Forest finds himself as reigning tour champion. The once 120+ score player has now turned his game into one of beautiful swings and impeccable putting (albeit with some controversy over the no. of clubs in his bag). There is no argument that watching Pussy swing a club is akin to a beautiful sunset on Balis Western Beaches or an underwater shot of the Swedish Synchronised diving team, an eye catching experience on multiple levels.\r\n\r\nPussy does take a while to warm up but used that to great advantage in 2013 (some would call it foxing) warming up through the seeding events and then coming to the apple isle in tip top form. Dont be fooled by Pussys unorthodox approach shots bringing bunkers, water, trees and GUR into play. His strong mid-range game is something to behold and his almost mechanical swing can remove most obstacles on his endeavour to getting the ball in the hole.\r\n\r\nStrength: Laser like precision  although not a long hitter, the accuracy of his long shots means precarious tee positioning doesnt put a ripple in his game.\r\n\r\nWeakness: Distance  a long hole can seem like an insurmountable task and dint his confidence.', '2013-08-11 13:41:43', 0, NULL, 'img/avatar/pussy.jpg', NULL, ''),
(16, 2, 'Andrew', 'Dorian', 'Hungry Jack', 'Generally a star of any event, the consistent Dozburger AKA "Hungry Jack" has a generally good all round game. Due to conflicting priorities he was nearly lost to the tour, preferring to "free ride", doing it all for the love of the game rather than the accolades. "Whopper" tends to shy away from the media to hit the practice fairway prior to the commencement of any round. His long, medium and short haul game are nothing short of precision. The "The Burger King" takes his ball selection seriously, switching between precision and distance at each tee. A lot of thought and consideration goes into his game, not only on the day but in the lead up to an event.\r\n\r\nStrength: Consistency - it`s hard to fault any part of his game.\r\n\r\nWeakness: Mental Toughness - with such careful consideration going into his all round game, a bit of well placed sledging can wreak havoc for the great man.', '2013-08-11 13:41:43', 0, NULL, 'img/avatar/hungryjack.jpg', NULL, ''),
(17, 2, 'Nic', 'Luiz', 'Dolphin', 'His long hitting ability, reminiscent of the great Greg Norman, makes him a formidable challenger; however it`s his coolness under pressure and ironically his adeptness at keeping clear of beach elements (sand and water) which make The Smoking Dolphin one of the drawcards of any event. The kid has guts, as shown by his ability to take on the 12th at Barnbougle Dunes and drive the green on the last day cementing second spot for the tournament after languishing for the first two days play.\r\n\r\nThe Dolphin relishes the competition, puffing his way around the course like a great 18th century locomotive. And like a locomotive he can be slow to warm up on the course, but once he gets going there is just a methodical consistency to his game that most can only dream of. Donning the NAGA jersey after the first days play in the 2013 event changed him, The Smoking Dolphin decided he didnt look good in high viz orange and vowed never to own the losers jersey again and that motivates him to this day.\r\n\r\nStrength: Courage  Give him a sub 300m par 4 and hell try to drive it, more often than not resulting in a positive position for his second shot (or first putt)\r\n\r\nWeakness: Roads  Ever since the Queens Way Incident, a road running parallel to the fairway is like kryptonite forcing a reserved tee shot.', '2013-08-11 13:41:43', 0, NULL, 'img/avatar/dolphin.jpg', NULL, ''),
(18, 2, 'Mark', 'Smith', 'Rimmer', 'Always short odds to win the hairiest man on course competition Rim Job has had a rollercoaster relationship with the golf. After taking the game up with gusto and showing flashes of brilliance, Rimmer had a poor run of form and addressed the worlds sporting media announcing his retirement from the game dropping the hickory sticks almost as quickly as he had picked them up. After a short sabbatical he realised he was too young to retire and slowly worked on his comeback  reinventing his swing and taking a fresh approach to the game. Journalists had doubts as to whether the wild man from Borneo had the patience and concentration to make the most of his raw talent, but have had to eat their words. The Rim is a quiet achiever who goes about his business with a modest approach, even denying the golf gods a celebration birdie dance now that he experiences them more regularly. Having not competed on the illustrious tour to date, it will be interesting to see how he handles the added pressure of world class competition.\r\n\r\nStrength: Tee Shots  His first shots usually setup the hole, and more often than not theyre on the money  short or long.\r\n\r\nWeakness: Putting  Can have a tendency to turn a great hole into something forgettable with 3+ putting.', '2013-08-11 13:41:43', 0, NULL, 'img/avatar/rim.jpg', NULL, ''),
(19, 2, 'Adam', 'Smith', 'Purple (Withdrawn)', 'When hes not out there breaking the big stories, youll find the Purple Headed Warrior on the course smacking them high and long down the fairway. His go-hard or go-home approach on the course makes him the X-Factor on any tour. He backs himself and plays ultra-aggressive golf and if on song early, rides the wave of confidence better than Kelly Slater - all the way back to the 19th hole.\r\n\r\nThere have been unconfirmed reports that Purple can be known to throw the odd club when things dont go his way, and his tendency to bail after a forgetful front 9 means that hes one to watch as you never know what might happen next. Having uprooted his family, moving to a golf course in a bid to get some consistency in his game after a dismal last place finish at the 2013 event, The Warrior is doing all he can to be in contention to one day hold the coveted trophy aloft.\r\n\r\nStrength: Distance  Hes a big hitter and relies on that to shorten the hole.\r\n\r\nWeakness: Wind  No, not the baked beans type. With his high trajectory and ball flight a decent headwind can severely hamper his long hitting ability.', '2013-08-11 13:41:43', 0, NULL, 'img/avatar/warrior.jpg', NULL, ''),
(20, 2, 'Paul', 'Sharp', 'The Marker', 'Fresh off the boat from Blighty, the Marker brings the tally of toff`s from the motherland to 3 making the Shankers a truly internationally attended tournament.\r\n\r\nLittle is known about the Marker`s line and length, but the years of experience in the wild and windy courses in Blighty mark him down as a wild card favourite at the autumnal Barnbougle links courses - the Marker will feel at home in the swirling wind at the Dunes.\r\n\r\nThe Marker`s years of ale drinking in the motherland will also put him in a prime position to take advantage of the early start on day 3 so look out for a late charge in the final round.  \r\n\r\nThe marker is one to watch - sure to make his mark', '2013-08-11 13:41:43', 0, NULL, 'img/avatar/marker.jpg', NULL, ''),
(22, 3, 'Richo', 'RIchardson', 'Moley', '<p class="lead">It doesn`t matter how early it might be, "The Mole" is always up for a cheeky 9 or 18. </p>\r\n\r\n<p>His inconsistent ball flight makes "Moley" ever so unpredictable on the course with a penchant for the worm burner AKA the mole raper. Even when he does get them in the air, his shots seem to skid on first bounce like Danny MacAskill on a BMX and double there distance on the ground. \r\n</p><p>\r\nThe man with the chrome dome doesn`t mind an accessory demonstrated by the loudmouth yuk pants and his GPS gadgets - "Moley" is always looking for an edge. After leading early in the 2012 event only to forfeit after a heavy night on the booze and being second place for most of 2013 to then finish second last there are serious question marks over whether "The Mole Raper" can go the distance. He`s hit the Jazzercise circuit hard in an attempt to reverse the trend of late round fade outs.</p>\r\n\r\n<blockquote class="right">"Sportsmanship for me is when a guy walks off the field and you really can`t tell whether he won or lost, when he carries himself with pride either way." <cite>- Moley</cite></blockquote>\r\n\r\n<p><b>Strength:</b> Short Game His work with the lobby and chipper tend to make up for an inconsistent long game.</p>\r\n\r\n<p><b>Weakness:</b> Sand - Bunkers are not his friend - especially those with trees or shrubs in them!</p>\r\nThe man with the chrome dome doesn`t mind an accessory demonstrated by the loudmouth yuk pants and his GPS gadgets - "Moley" is always looking for an edge. After leading early in the 2012 event only to forfeit after a heavy night on the booze and being second place for most of 2013 to then finish second last there are serious question marks over whether "The Mole Raper" can go the distance. He`s hit the Jazzercise circuit hard in an attempt to reverse the trend of late round fade outs.', '2014-07-10 12:05:38', 0, NULL, 'img/avatar/mole.png', '9.9', ''),
(21, 2, 'Steve', 'Wilkinson', 'The Moth', 'A newcomer to the Shankers, the Moth (who does his best work at night) is a welcome sight to the current English contingent on tour. With the dolphin the only one who has seen the Moth in action there is much anticipation and expectation on the Moth both on and off the golf course. On the course the Moth will be an imposing player who will give the coveted leaders vest a good shake. \r\n\r\nA strong consistent drive and good short game has the moth well placed to be one of the favourites for the tournament. What remains to be seen is if the Moth can back up after a night on the turps. Injuries will play a big factor on his performance with knee`s, back and given his age, hips being continuously worked on by the Happy Ending Physiotherapy group leading up to the tournament.\r\n\r\nQuestions have been raised about the Moth`s commitment with delayed entrance fee payments and a notable absentee from the first seeding event. Whether this is over confidence or setting the bar low, only time will tell.\r\n\r\nStrength: Great overall game consistency, handles pressure on the big occasion well and will give Pussy a run for his money on the 19th.\r\n\r\nWeakness: Lack of match practice, injuries and questions over his ability to back up after a big night out. Not a big fan of anything other than beer could be his Achilles heel.', '2013-08-11 13:41:43', 0, NULL, 'img/avatar/moth.jpg', NULL, ''),
(23, 3, 'Jules', 'Stevenson', 'Pussy', '<p class="lead">The antipodal version of the great Tiger Woods, Pussy Forest finds himself as defeated tour champion, having taken out the trophy in 2013</p>\r\n\r\n<p>The once 120+ score player has now turned his game into one of beautiful swings and impeccable putting (albeit with some controversy over the no. of clubs in his bag). There is no argument that watching Pussy swing a club is akin to a beautiful sunset on Balis Western Beaches or an underwater shot of the Swedish Synchronised diving team, an eye catching experience on multiple levels.\r\n</p><p>\r\nPussy does take a while to warm up but used that to great advantage in 2013 (some would call it foxing) warming up through the seeding events and then coming to the apple isle in tip top form. Dont be fooled by Pussys unorthodox approach shots bringing bunkers, water, trees and GUR into play. His strong mid-range game is something to behold and his almost mechanical swing can remove most obstacles on his endeavour to getting the ball in the hole.\r\n</p>\r\n<blockquote class="right">"\r\nA couple more cheeky fellas before tee-off should help my game no end.  \r\n<cite>- Pussy</cite></blockquote>\r\n<p><b>Strength: Laser like precision  although not a long hitter, the accuracy of his long shots means precarious tee positioning doesn`t put a ripple in his game.\r\n\r\n</b></p>\r\n<p><b>Weakness: Distance  a long hole can seem like an insurmountable task and dint his confidence.\r\n</b></p>', '2014-07-10 12:05:38', 0, NULL, 'img/avatar/pussy.png', '9.9', ''),
(24, 3, 'Nic', 'Luiz', 'Dolphin', '<p class="lead">His long hitting ability, reminiscent of the great Greg Norman, makes him a formidable challenger; however it`s his coolness under pressure and ironically his adeptness at keeping clear of beach elements (sand and water) which make The Smoking Dolphin one of the drawcards of any event. </p>\r\n\r\n<p>The kid has guts, as shown by his ability to take on the 12th at Barnbougle Dunes and drive the green on the last day cementing second spot for the tournament after languishing for the first two days play.</p>\r\n\r\n<p>The Dolphin relishes the competition, puffing his way around the course like a great 18th century locomotive. And like a locomotive he can be slow to warm up on the course, but once he gets going there is just a methodical consistency to his game that most can only dream of. Donning the NAGA jersey after the first days play in the 2013 event changed him, The Smoking Dolphin decided he didnt look good in high viz orange and vowed never to own the losers jersey again and that motivates him to this day.</p>\r\n\r\n<blockquote class="right">"It`s not the way that you win which matters.  It`s all about the winning. And I`m a winner." <cite>- Dolphin</cite></blockquote>\r\n\r\n\r\n<p><b>Strength: Courage  Give him a sub 300m par 4 and hell try to drive it, more often than not resulting in a positive position for his second shot (or first putt)</b></p>\r\n\r\n<p><b>Weakness: Roads  Ever since the Queens Way Incident, a road running parallel to the fairway is like kryptonite forcing a reserved tee shot.</b></p>', '2014-07-10 12:05:38', 0, NULL, 'img/avatar/dolphin.png', '9.9', ''),
(25, 3, 'Mark', 'Smith', 'Rimmer', '<p class="lead">Always short odds to win the hairiest man on course competition Rim Job has had a rollercoaster relationship with the golf. \r\n</p>\r\n\r\n<p>After taking the game up with gusto and showing flashes of brilliance, Rimmer had a poor run of form and addressed the worlds sporting media announcing his retirement from the game dropping the hickory sticks almost as quickly as he had picked them up. After a short sabbatical he realised he was too young to retire and slowly worked on his comeback  reinventing his swing and taking a fresh approach to the game. </p>\r\n\r\n<p>Journalists had doubts as to whether the wild man from Borneo had the patience and concentration to make the most of his raw talent, but have had to eat their words. </p>\r\n\r\n<p>The Rim is a quiet achiever who goes about his business with a modest approach, even denying the golf gods a celebration birdie dance now that he experiences them more regularly. Having not competed on the illustrious tour to date, it will be interesting to see how he handles the added pressure of world class competition.\r\n\r\n</p>\r\n\r\n<blockquote class="right">"Consistency`s the key to unlocking this tournament.  I`m locked out of the consistency dungeon " <cite>- Rimmer</cite></blockquote>\r\n\r\n\r\n<p><b>Strength: Tee Shots  His first shots usually setup the hole, and more often than not theyre on the money  short or long.</b></p>\r\n\r\n<p><b>Weakness: Putting  Can have a tendency to turn a great hole into something forgettable with 3+ putting.</b></p>', '2014-07-10 12:05:38', 0, NULL, 'img/avatar/rim.jpg', '9.9', ''),
(26, 3, 'Paul', 'Sharp', 'The Marker', '<p class="lead">Fresh off the boat from Blighty, the Marker brings the tally of toff`s from the motherland to 3 making the Shankers a truly internationally attended tournament.</p>\r\n\r\n<blockquote class="right">"Getting a good night`s sleep is all part of the pre-match prep.  I`ll be asleep at 9.07pm no matter where I am." <cite>- Marker</cite></blockquote>\r\n\r\n<p><b>Strength: Marker`s swing is poetry in motion, on his day he`ll give Tiger a run for his money</b></p>\r\n\r\n<p><b>Weakness: Age is taking it`s toll on his body and his ability to stay awake at the bar.</b></p>', '2014-07-10 12:05:38', 0, NULL, 'img/avatar/marker.png', '9.9', ''),
(27, 3, 'Adam', 'Smith', 'Purple', '<p class="lead">The Purple Headed Warrior is BACK!</p>\r\n\r\n<blockquote class="right">"Wow, it feels great to be back after the lost years in the wilderness." <cite>- Purple</cite></blockquote>\r\n\r\n<p><b>Strength: Himself.</b></p>\r\n\r\n<p><b>Weakness: Himself</b></p>', '2014-12-07 08:06:47', 0, NULL, 'img/avatar/warrior.png', '9.9', ''),
(28, 4, 'Pussy', 'Forest', 'Pussy', '<p class="lead">Pussy Forest has managed to wear the leaders jersey an astonishing four times!</p>\r\n\r\n<p>In 2013 he led from start to finishing wearing the coveted vest 3 times and after not troubling the scorers too much in 2014, he was again back in the vest after the first round for 2015. Although unable to take out the major prize in 2015, Pussy has a new found love for the game and has continued his training regime post tournament. With his gout, dickey knee and tennis elbow well and truly behind him the sky is the limit! \r\n</p>\r\n\r\n<p><b>Tour Status:</b> Tournament President</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 1st - 2013</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2013, 2014, 2015</p>\r\n\r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Inaugural Winner (2013)</li>\r\n<li>Highest Handicap (2013, 2014, 2015)</li>\r\n<li>Best Tournament Planning (2014, 2015)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> Strategic play in the 2013 seeding events to maximise the handicap coming into the tournament and then peeling off the 3 best rounds of his life with the new Callaway X-Hot`s!</p>\r\n\r\n<p>\r\n<blockquote class="right">"I wouldn`t even spit on a pair of tiger bather board shorts if they cost under $400." <cite>- Pussy</cite></blockquote>\r\n</p>', '2015-05-05 07:22:13', 0, NULL, 'img/avatar/pussy2016.jpg', '9.9', ''),
(29, 4, 'Purple', 'Warrior', 'Purple', '<p class="lead">After a year in the wilderness Purple returned for the 2015 tournament and was reminded of the hard work and dedication it takes to be at the top.</p>\r\n\r\n<p>After an inconsistent seeding tour and a poor on course performance in the 2015 main event, Purple has already started his training regime for 2016. He`s on the course every week, and early reports are very positive. The only question is whether golf can hold his interest for the next 12 months...\r\n</p>\r\n\r\n<p><b>Tour Status:</b> Associate Member</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 4th (NAGA) 2013</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2013, 2015</p>\r\n\r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Most Broken Clubs (2015)</li>\r\n<li>Best Off Course (2015)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> Buying a golf cart.</p>\r\n\r\n<p>\r\n<blockquote class="right">"My wife said I had to choose between her and golf... Gee, sometimes I miss my wife." <cite>- Purple</cite></blockquote>\r\n</p>', '2015-05-05 07:43:05', 0, NULL, 'img/avatar/purple2016.jpg', '9.9', ''),
(30, 4, 'Hungry', 'Jack', 'Hungry', '<p class="lead">Hungry Jack was devastated to miss the tournament this year, only one tournament showing means he`s a junior member.</p>\r\n\r\n<p>However, he showed some great form in the seeding events this year, it must have hurt that he was ineligible to claim any prizes. Hungry can sit back and relax confident in the knowledge he has the technique and dedication required to mix it with the best. He`s the only man on tour who has ever requested his handicap to be lowered - now that`s confidence!!!\r\n</p>\r\n\r\n<p><b>Tour Status:</b> Junior Member</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 3rd - 2014</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2014</p>\r\n\r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Seeding Tour Winner (2014)</li>\r\n<li>Most Range Balls Hit at a Tournament (2014)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> Turning up late at Portsea golf course, arriving as the group Tee`d off on the second hole with brand new clubs still individually shrink wrapped.</p>\r\n<p>\r\n\r\n<blockquote class="right">"6 P`s - Perfect preparation prevents piss poor performance." <cite>- Hungry</cite></blockquote>\r\n</p>', '2015-05-05 07:47:19', 0, NULL, 'img/avatar/hungry2016.jpg', '9.9', ''),
(31, 4, 'Smokin', 'Dolphin', 'Dolphin', '<p class="lead">The Dolphin is the most intriguing player on the tour.</p>\r\n\r\n<p>He has the game to match it with the best, and plays well for big chunks of time, but as yet hasn`t been able to bring it all together on the big weekend. This year he achieved his goal of making the NAGA vest of 2014 a distant memory, now he just needs to add consistency to his game in order to see his name on the trophy in 2016.</p>\r\n\r\n<p><b>Tour Status:</b> Senior Member</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 2nd - 2013</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2013, 2014, 2015</p>\r\n \r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Best Drive (2013)</li>\r\n<li>Best Use of a Power Play (2015)</li>\r\n<li>Highest Score on 9 (2014)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> One can`t go past the Dolphin`s Greg Norman-esque drive on the 17th at Albert Park. He belted the stuffing out of the ball... Unfortunately the radar was a little off and it went straight out onto Queens Rd and into some poor blokes week old Nissan.</p>\r\n<p>\r\n\r\n<blockquote class="right">"Yes I know we`re heading off from Tullamarine, but you have organised a private jet right?... Okay so first class?... No? This is bullshit!" <cite>- The Smokin` Dolphin</cite></blockquote>\r\n</p>', '2015-05-09 04:25:47', 0, NULL, 'img/avatar/dolphin2015.PNG', '9.9', ''),
(32, 4, 'Mole', 'Scraper', 'Moley', '<p class="lead">Moley`s rise up the leader table has been more glacial than meteoric.</p>\r\n\r\n<p>2nd from bottom in the inaugural event, mid-table in 2014 and an impressive 2nd place in 2015 suggests 2016 could be Moley`s year.  On his day, Moley can break records - as the holder of the highest 1 day score in Shankers history - but Moley`s tendency to post one mediocre score for every two great scores sees his leaderboard position bounce up and down like a whore`s drawers.  If he can post 3 solid rounds in 2016 there`s a good chance his 4 year project plan towards Shankers glory will have been executed to perfection.</p>\r\n\r\n<p><b>Tour Status:</b> Tournament Steward & Chairman</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 2nd - 2015</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2013, 2014, 2015</p>\r\n\r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Highest score for a tournament round with 60 (2014)</li>\r\n<li> Nearest the pin winner by a mile (2014)</li>\r\n<li>Best and fairest handicapping of Shankers (2015)</li>\r\n<li>Most controversial handicapping of Shankers (2013)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> With an endless list of golfing achievements (including invention of the 38 handicap in 2014/2015 seeding competition), it`s hard to pick just one.  But arguably Moley`s greatest achievement is his uncanny ability to chip into the cup from impossible distances and angles.  Give that man a wedge and he`ll land his balls in any hole with military precision.</p>\r\n\r\n<p>\r\n<blockquote class="right">"Errr....how.....what...wh...how, err, did you get in here? Where am I?" <cite>- Moley (Coolum Wake Up Call, 2015)</cite></blockquote>\r\n</p>', '2015-05-11 10:51:55', 0, NULL, 'img/avatar/moley2015.PNG', '9.9', ''),
(33, 4, 'Rim', 'Job', 'Rimmer', '<p class="lead">Rim Job celebrated his maiden tournament victory in style, pole dancing his way around Australia`s best strip clubs.</p>\r\n\r\n<p>Still not having picked up a club since his victory, some pundits are saying he`s already out of the race for backing it up in 2016. Not so, Rimmer knows what it takes to climb the mountain, dominating the field from the kick-off of the seeding rounds all the way through to the final day of the tournament. Since claiming victory he`s taken ownership of a house, painted it, and setup an empty shelf pride of place where he intends the trophy to sit, not just this year, but beyond.</p>\r\n\r\n<p><b>Tour Status:</b> Associate Member & Champion</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 1st - 2015</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2014, 2015</p>\r\n\r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Tournament Winner (2015)</li>\r\n<li> Seeding Tour Winner (2015)</li>\r\n<li>Most Golfing YouTube Video`s Watched (2014)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> If you ask Rimmer he would probably say his eagle on the par 5 at Yarra Bend. But dig a little deeper into the archives and there`s a little known gem. Teeing off for a game with his finances boss, Rim Job somehow managed to hook a ball vicously and have it travel at a cracking pace on a 45 degree angle backwards - straight smack into his playing partners remote control buggy. Serves the bloke right for having a remote control buggy!</p>\r\n\r\n<p>\r\n<blockquote class="right">"I`m not saying I think I have the power to control birds. I`m just saying if one day I discover I have the power to control birds, that would not surprise me" <cite>- Rim Job</cite></blockquote>\r\n</p>', '2015-05-29 07:52:02', 0, NULL, 'img/avatar/rimmer2015.jpg', '9.9', ''),
(34, 4, 'The', 'Marker', 'Marker', '<p class="lead">Let me throw a couple of stats at you:</p>\r\n\r\n<p>The Marker averages a whopping 42 Stableford points per tournament round and an absolutely astounding 43 on the dreaded day 2! He`s a bit unfortunate, he has obvious talent and scores to match, and was so unlucky to lose the 2014 tournament by 7 Stableford points after amassing 141 for the weekend and owning the yellow vest for 98% of that time. That`s the thing about the Shankers, it`s tougher than a two dollar stake. Don`t write the boy from York County off though. With a knee realignment in the off season, Marker has put a circle around October 11th on the calendar, the day 2016 seeding begins - redemption...</p>\r\n\r\n<p><b>Tour Status:</b> Associate Member</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 2nd - 2014</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2014, 2015</p>\r\n\r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Highest score for an opening tournament round with 51 (2014)</li>\r\n<li> Most wears of the yellow vest without winning a tournament (2014)</li>\r\n<li>Best off course (2014)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> On day 2 of the 2014 Shankers most players tee`d off with the confidence that they would at least beat the Marker. At 10:30pm the night before, he had been found passed out between the front door of his cottage and his bed. But on a day at Lost Farm that was windier than a 50 pound bag of whistling lips, Marker peeled off a lazy 40 point round to do enough to retain the yellow vest after the close of play. Pure brilliance!</p>\r\n\r\n<p>\r\n<blockquote class="right">"I love jalapeno`s, the more the better, I cannot get enough. My motto is - if it isn`t going to burn the ring, then don`t eat the thing!" <cite>- The Marker</cite></blockquote>\r\n</p>', '2015-05-29 07:52:02', 0, NULL, 'img/avatar/marker2015.png', '9.9', ''),
(35, 5, 'The', 'Marker', 'Marker', '<p class="lead">Let me throw a couple of stats at you:</p>\r\n\r\n<p>The Marker averages a whopping 42 Stableford points per tournament round and an absolutely astounding 43 on the dreaded day 2! He`s a bit unfortunate, he has obvious talent and scores to match, and was so unlucky to lose the 2014 tournament by 7 Stableford points after amassing 141 for the weekend and owning the yellow vest for 98% of that time. That`s the thing about the Shankers, it`s tougher than a two dollar stake. Don`t write the boy from York County off though. With a knee realignment in the off season, Marker has put a circle around October 11th on the calendar, the day 2016 seeding begins - redemption...</p>\r\n\r\n<p><b>Tour Status:</b> Associate Member</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 2nd - 2014</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2014, 2015, 2016</p>\r\n\r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Highest score for an opening tournament round with 51 (2014)</li>\r\n<li> Most wears of the yellow vest without winning a tournament (2014)</li>\r\n<li>Best off course (2014)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> On day 2 of the 2014 Shankers most players tee`d off with the confidence that they would at least beat the Marker. At 10:30pm the night before, he had been found passed out between the front door of his cottage and his bed. But on a day at Lost Farm that was windier than a 50 pound bag of whistling lips, Marker peeled off a lazy 40 point round to do enough to retain the yellow vest after the close of play. Pure brilliance!</p>\r\n\r\n<p>\r\n<blockquote class="right">"I love jalapeno`s, the more the better, I cannot get enough. My motto is - if it isn`t going to burn the ring, then don`t eat the thing!" <cite>- The Marker</cite></blockquote>\r\n</p>', '0000-00-00 00:00:00', 0, NULL, 'img/avatar/marker2015.png', '9.9', ''),
(36, 5, 'Smokin', 'Dolphin', 'Dolphin', '<p class="lead">The Dolphin is the most intriguing player on the tour.</p>\r\n\r\n<p>He has the game to match it with the best, and plays well for big chunks of time, but as yet hasn`t been able to bring it all together on the big weekend. This year he achieved his goal of making the NAGA vest of 2014 a distant memory, now he just needs to add consistency to his game in order to see his name on the trophy in 2016.</p>\r\n\r\n<p><b>Tour Status:</b> Senior Member</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> Shankers Champion - 2016</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2013, 2014, 2015, 2016</p>\r\n \r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Best Drive (2013)</li>\r\n<li>Best Use of a Power Play (2015)</li>\r\n<li>Highest Score on 9 (2014)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> One can`t go past the Dolphin`s Greg Norman-esque drive on the 17th at Albert Park. He belted the stuffing out of the ball... Unfortunately the radar was a little off and it went straight out onto Queens Rd and into some poor blokes week old Nissan.</p>\r\n<p>\r\n\r\n<blockquote class="right">"Yes I know we`re heading off from Tullamarine, but you have organised a private jet right?... Okay so first class?... No? This is bullshit!" <cite>- The Smokin` Dolphin</cite></blockquote>\r\n</p>', '2016-08-21 04:25:47', 0, NULL, 'img/avatar/dolphin2015.PNG', '9.9', ''),
(37, 5, 'Pussy', 'Forest', 'Pussy', '<p class="lead">Pussy Forest has managed to wear the leaders jersey an astonishing four times!</p>\r\n\r\n<p>In 2013 he led from start to finishing wearing the coveted vest 3 times and after not troubling the scorers too much in 2014, he was again back in the vest after the first round for 2015. Although unable to take out the major prize in 2015, Pussy has a new found love for the game and has continued his training regime post tournament. With his gout, dickey knee and tennis elbow well and truly behind him the sky is the limit! \r\n</p>\r\n\r\n<p><b>Tour Status:</b> Tournament President</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 1st - 2013</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2013, 2014, 2015, 2016</p>\r\n\r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Inaugural Winner (2013)</li>\r\n<li>Highest Handicap (2013, 2014, 2015)</li>\r\n<li>Best Tournament Planning (2014, 2015)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> Strategic play in the 2013 seeding events to maximise the handicap coming into the tournament and then peeling off the 3 best rounds of his life with the new Callaway X-Hot`s!</p>\r\n\r\n<p>\r\n<blockquote class="right">"I wouldn`t even spit on a pair of tiger bather board shorts if they cost under $400." <cite>- Pussy</cite></blockquote>\r\n</p>', '2016-08-21 07:22:13', 0, NULL, 'img/avatar/pussy2016.jpg', '9.9', ''),
(38, 5, 'Hungry', 'Jack', 'Hungry', '<p class="lead">Hungry Jack was devastated to miss the tournament this year, only one tournament showing means he`s a junior member.</p>\r\n\r\n<p>However, he showed some great form in the seeding events this year, it must have hurt that he was ineligible to claim any prizes. Hungry can sit back and relax confident in the knowledge he has the technique and dedication required to mix it with the best. He`s the only man on tour who has ever requested his handicap to be lowered - now that`s confidence!!!\r\n</p>\r\n\r\n<p><b>Tour Status:</b> Junior Member</p>\r\n\r\n<p><b>Highest Tournament Finish:</b> 3rd - 2014</p>\r\n\r\n<p><b>Tournaments Attended:</b> 2014, 2016</p>\r\n\r\n<p><b>Tour Accolades:</b> <ul>\r\n<li>Seeding Tour Winner (2014)</li>\r\n<li>Most Range Balls Hit at a Tournament (2014)</li>\r\n</ul></p>\r\n\r\n<p><b>Greatest Golfing Achievement:</b> Turning up late at Portsea golf course, arriving as the group Tee`d off on the second hole with brand new clubs still individually shrink wrapped.</p>\r\n<p>\r\n\r\n<blockquote class="right">"6 P`s - Perfect preparation prevents piss poor performance." <cite>- Hungry</cite></blockquote>\r\n</p>', '2016-08-21 07:47:19', 0, NULL, 'img/avatar/hungry2016.jpg', '9.9', ''),
(39, 6, 'Pussy', 'Forest', 'Pussy', '<p class="lead">Trevor says...</p>\r\n\r\n<p>On the way home from a recent book signing for my latest romantic novella "Love on the Fairway", I decided to do some intense research on the reigning NAGA. Let me tell you - never google "Pussy Forest" on a packed train! That sh1t cannot be unseen, but I must say it was great to see some old fashioned 70`s bush... but I digress.</p> \r\n\r\n<p>Pussy clearly means business for 2018. After middling his way through most tournaments, 2017 saw him get a taste of being NAGA. Whilst he relished the opportunity to play with pink balls, Blind Freddy can see that he`s got bigger plans this year. He`s taking the unprecedented step of removing all distractions in the lead up to the tournament, even quitting his job to clear the month prior and hone his golf game. </p>\r\n\r\n<p>Pussy`s obvious plan is to capitalise on his new found consistency and still generous handicap to try and legitimately get his name on the trophy for the first time and silence the doubters. A Winx like unbackable favourite for the 2018 title at $1.03, it`s amazing to see how Pussy has progressed over the years. The time is right for another NAGA-to-Champion upset and only Jack Daniels and James Boag stand in his way. </p>\r\n\r\n<p>Can Pussy resist the temptation of a few beers during the tournament to savour drinking champaigne from the winners cup at the end? This writer is betting he will!</p>\r\n\r\n<p>\r\n<blockquote class="right">"This is serious - no time for banter" <cite>- Pussy</cite></blockquote>\r\n</p>', '2016-08-21 07:22:13', 0, NULL, 'img/avatar/pussy2016.jpg', '29.6', '3413300591'),
(40, 6, 'Hungry', 'Jack', 'Hungry', '<p class="lead">Trevor says...</p>\r\n\r\n<p>Hungry is a new man. Broken after receiving the NAGA in 2016 he put in a hurculean effort to become the first NAGA to Shanker Champion in 2017. </p>\r\n\r\n<p>Never a stranger to controversy, his victory coincided with turning up to a Shankers Tournament sans his official shakers polo as he battled his way through penalties which meant various holes across the weekend could only be played  using a single club. So laser focused was the man that he was guilty of leaving his cart companion in the dust as he relentlessly persued glory.... but glory he did taste. </p>\r\n\r\n<p>The Hangry Hungry Hippo faces some new challenges in 2018; he`ll be the hunted instead of the hunter, his low handicap adds further pressure to be on top of his game 100% of the time. However, the true mental battle for Hungry may not be driven by his tournament ranking. Hangry has always been safe in the knowledge that no matter the tournament result, he`s the best player in the field off the stick - Man vs. Course, handicaps ignored the Hippo is the Alpha Predator. But with the addition of the Horse Whisperer to the tournament contingent that status is under threat. Diamonds are made under pressure, and I`m going to be glued to my seat watching to see if Hungry can rise above it all to become the inaugral dual champ!!</p>\r\n\r\n<blockquote class="right">"Grass as in `Gas, grass or arse, you ride, you pay.`? Or Grass as in the stuff a good Shanker avoids when on a golf course?" <cite>- Hungry</cite></blockquote>\r\n</p>', '2016-08-21 07:47:19', 0, NULL, 'img/avatar/hungry2016.jpg', '10.5', '3413300590'),
(41, 6, 'Smokin', 'Dolphin', 'Dolphin', '<p class="lead">Trevor says...</p>\r\n\r\n<p>With a smile on his face and a dart between the fingers, the Dolphin has strapped himself in and looks prepared to accept the next turn in the `stock market like` results Shankers throws at him. </p>\r\n<p>He`s experienced Championship highs, and crying game shower scene inducing NAGA lows in his 5 years on tour and is chomping at the bit for the next installment. \r\nHe knows that to be a champion Shanker he can`t focus on golf alone; the Tournament weekend is a gruelling mix of Golf, Banter and Booze which need to be negotiated with aplomb.</p> \r\n<p>After some early Nanna like technology trouble with WhatsApp he`s worked hard on his banter skills - dropping the odd mic dropping calls on chat and email. He`s also prepared hard booze-wise, and is in top form after a recent interstate winery trip.</p>\r\n<p>Although controversially ineligible for a Tournament Bonus Point, the Dolphin is one of the in form players coming out of the Seeding Season. His previously outrageously generous handicap has dropped back a bit, but with all his off course preparation he`s a shoe in for the tittle.... as long as he can swing the clubs in decent fashion for around 15 hours over 3 days.\r\n</p>\r\n\r\n<blockquote class="right">"Never said no to a good club polish" <cite>- The Smokin` Dolphin</cite></blockquote>\r\n</p>', '2016-08-21 04:25:47', 0, NULL, 'img/avatar/dolphin2015.PNG', '27.5', '3413300587'),
(42, 6, 'The', 'Marker', 'Marker', '<p class="lead">Trevor says...</p>\r\n\r\n<p>Perception is that Marker is the most deserving competitor never to take home the trophy, but as I sit here on the couch with Doritos all over my bare chest I question how accurate this is. </p>\r\n<p>The bloke hardly turns up to a Seeding event and 50% of the time uses any excuse under the sun not to submit his scorecard. The bald eagle surely has the talent to win and a commitment to the tournament weekend like no other, but his commitment to preparations seems to be lacking. \r\n</p><p>We all know the old saying "Those who fail to prepare, have to be prepared to fail". That being said, there is method to the mans seeming madness. It`s rumoured Marker spent the off season with Tibetan Monks searching for enlightenment, where the Grand Puba bestowed his wisdom - The value of a tournament bonus point outweighs a handful of stableford points across the weekend. </p><p>So Marker set about his limited Seeding with renewed purpose - no longer worried about protecting his handicap, he played with gusto and (somewhat dubiously) reduced it by 10%, thus earning himself a very valuable edge on the competition. As Marker sits patiently polishing his wood and kneading his balls, he knows that the trophy is within reach... all he has to do is demolish Pussy in the off course drinking and he`ll be well on the way to victory.\r\n</p>\r\n\r\n<p>\r\n<blockquote class="right">"This group is about Shankers, not family days out, or digging up some old shag!" <cite>- The Marker</cite></blockquote>\r\n</p>', '0000-00-00 00:00:00', 0, NULL, 'img/avatar/marker2015.png', '24.6', '3413300610'),
(43, 6, 'Mole', 'Scraper', 'Moley', '<p class="lead">Trev Says...</p>\r\n\r\n<p>After withdrawal from the 2017 competition and being relegated to watching the rAdelaide Tournament events unfold in his Y-fronts on the couch through the WhatsApp feed, Moley seems keen to make an impact this year. </p>\r\n\r\n<p>By outsourcing handicapping duties to the Social Golf Club and Golf Australia, Moley is now free to focus on his own game without worrying about the inevitable integrity questions and incessant banter that a win under his own stewardship would have brought. </p><p>Lifting the 2018 trophy will be a challenge for the man with the lowest altitude 200m drive on record and he`ll need to overcome his current over reliance on spectacular golfing shots to counteract the holes where he has more shots than a depressed bridesmaid at a hens party. </p><p>\r\nThe quality of this year`s field leaves him nowhere to hide and not being able practice his actual golf game as much as he`d like, Moley is looking to non conventional tactics to try and enhance his game. We`ll see another spike in Herbalife shares if his strategy of decaf green tea, nonchalant zen like swing, meditating whilst caressing dirty golf balls and performing the Haka prior to tee off pays dividends.</p>\r\n\r\n<p>\r\n<blockquote class="right">"I excel at organising golf trips, just not playing in them " <cite>- Moley </cite></blockquote>\r\n</p>', '2015-05-11 10:51:55', 0, NULL, 'img/avatar/moley2015.PNG', '24.8', '3413300028'),
(44, 6, 'Farrier', 'McKnight', 'Farrier', '<p class="lead">Trevor says...</p>\r\n\r\n<p>He`s trained horses to dominant race victories, excelled in country cricket teams and sparred shot for shot with Aaron Baddley on the junior golfing circuit - a pretty solid sporting career one might say. </p><p>Alas, the Farrier could never put his finger on it, but always felt there was something missing.... Until now! </p><p>\r\nFor a married man who has a daughter, some pundits felt he might have been over stating it when he described receiving his official Shankers 2018 Invitation as "... unequivocally the happiest day of my life!". But in a recent interview with yours truly when I was a respected journalist at Golf Quarterly, Farrier put further context to his comments "... it`s like all your life you dream of something bigger, and you`re just waiting for the day ShITOC recognises you and invites you on the tour. My chance is now, and I plan to take it by the short and curlies and give it the best shot I can." </p><p>\r\nThe man from Maldon joins the tour as the best handicapped golfer in the 2018 line up. He has confidence to spare and will surely be in contention for the best banter on tour award. Although unarguably talented, the low margin for error afforded by his handicap will be the true test for this man over the gruelling 3-day tournament. With no previous form to go by I`ll be very interested to see how his golf game handles the seedy mornings and the added pressure of Power Plays!\r\n</p>\r\n\r\n<p>\r\n<blockquote class="right">"Seriously getting stooged by you blokes. How can I be giving away 20 shots before we even tee off. Next thing you will all want to be teeing off the red markers and wearing skirts!!" <cite>- The Farrier</cite></blockquote>\r\n</p>', '2018-01-22 00:00:00', 0, NULL, 'img/avatar/farrier.png', '8.0', ''),
(45, 7, 'Pussy', 'Forest', 'Pussy', '<p class="lead">Trevor says...</p>\r\n\r\n<p>On the way home from a recent book signing for my latest romantic novella "Love on the Fairway", I decided to do some intense research on the reigning NAGA. Let me tell you - never google "Pussy Forest" on a packed train! That sh1t cannot be unseen, but I must say it was great to see some old fashioned 70`s bush... but I digress.</p> \r\n\r\n<p>Pussy clearly means business for 2018. After middling his way through most tournaments, 2017 saw him get a taste of being NAGA. Whilst he relished the opportunity to play with pink balls, Blind Freddy can see that he`s got bigger plans this year. He`s taking the unprecedented step of removing all distractions in the lead up to the tournament, even quitting his job to clear the month prior and hone his golf game. </p>\r\n\r\n<p>Pussy`s obvious plan is to capitalise on his new found consistency and still generous handicap to try and legitimately get his name on the trophy for the first time and silence the doubters. A Winx like unbackable favourite for the 2018 title at $1.03, it`s amazing to see how Pussy has progressed over the years. The time is right for another NAGA-to-Champion upset and only Jack Daniels and James Boag stand in his way. </p>\r\n\r\n<p>Can Pussy resist the temptation of a few beers during the tournament to savour drinking champaigne from the winners cup at the end? This writer is betting he will!</p>\r\n\r\n<p>\r\n<blockquote class="right">"This is serious - no time for banter" <cite>- Pussy</cite></blockquote>\r\n</p>', '2016-08-21 07:22:13', 0, NULL, 'img/avatar/pussy2016.jpg', '28.9', '3413300591');
INSERT INTO `golfer` (`id`, `compid`, `firstname`, `lastname`, `nickname`, `description`, `createddate`, `admin`, `yearid`, `avatar`, `handicap`, `golflink`) VALUES
(46, 7, 'Hungry', 'Jack', 'Hungry', '<p class="lead">Trevor says...</p>\r\n\r\n<p>Hungry is a new man. Broken after receiving the NAGA in 2016 he put in a hurculean effort to become the first NAGA to Shanker Champion in 2017. </p>\r\n\r\n<p>Never a stranger to controversy, his victory coincided with turning up to a Shankers Tournament sans his official shakers polo as he battled his way through penalties which meant various holes across the weekend could only be played  using a single club. So laser focused was the man that he was guilty of leaving his cart companion in the dust as he relentlessly persued glory.... but glory he did taste. </p>\r\n\r\n<p>The Hangry Hungry Hippo faces some new challenges in 2018; he`ll be the hunted instead of the hunter, his low handicap adds further pressure to be on top of his game 100% of the time. However, the true mental battle for Hungry may not be driven by his tournament ranking. Hangry has always been safe in the knowledge that no matter the tournament result, he`s the best player in the field off the stick - Man vs. Course, handicaps ignored the Hippo is the Alpha Predator. But with the addition of the Horse Whisperer to the tournament contingent that status is under threat. Diamonds are made under pressure, and I`m going to be glued to my seat watching to see if Hungry can rise above it all to become the inaugral dual champ!!</p>\r\n\r\n<blockquote class="right">"Grass as in `Gas, grass or arse, you ride, you pay.`? Or Grass as in the stuff a good Shanker avoids when on a golf course?" <cite>- Hungry</cite></blockquote>\r\n</p>', '2016-08-21 07:47:19', 0, NULL, 'img/avatar/hungry2016.jpg', '13.0', '3413300590'),
(47, 7, 'Smokin', 'Dolphin', 'Dolphin', '<p class="lead">Trevor says...</p>\r\n\r\n<p>With a smile on his face and a dart between the fingers, the Dolphin has strapped himself in and looks prepared to accept the next turn in the `stock market like` results Shankers throws at him. </p>\r\n<p>He`s experienced Championship highs, and crying game shower scene inducing NAGA lows in his 5 years on tour and is chomping at the bit for the next installment. \r\nHe knows that to be a champion Shanker he can`t focus on golf alone; the Tournament weekend is a gruelling mix of Golf, Banter and Booze which need to be negotiated with aplomb.</p> \r\n<p>After some early Nanna like technology trouble with WhatsApp he`s worked hard on his banter skills - dropping the odd mic dropping calls on chat and email. He`s also prepared hard booze-wise, and is in top form after a recent interstate winery trip.</p>\r\n<p>Although controversially ineligible for a Tournament Bonus Point, the Dolphin is one of the in form players coming out of the Seeding Season. His previously outrageously generous handicap has dropped back a bit, but with all his off course preparation he`s a shoe in for the tittle.... as long as he can swing the clubs in decent fashion for around 15 hours over 3 days.\r\n</p>\r\n\r\n<blockquote class="right">"Never said no to a good club polish" <cite>- The Smokin` Dolphin</cite></blockquote>\r\n</p>', '2016-08-21 04:25:47', 0, NULL, 'img/avatar/dolphin2015.PNG', '25.7', '3413300587'),
(48, 7, 'The', 'Marker', 'Marker', '<p class="lead">Trevor says...</p>\r\n\r\n<p>Perception is that Marker is the most deserving competitor never to take home the trophy, but as I sit here on the couch with Doritos all over my bare chest I question how accurate this is. </p>\r\n<p>The bloke hardly turns up to a Seeding event and 50% of the time uses any excuse under the sun not to submit his scorecard. The bald eagle surely has the talent to win and a commitment to the tournament weekend like no other, but his commitment to preparations seems to be lacking. \r\n</p><p>We all know the old saying "Those who fail to prepare, have to be prepared to fail". That being said, there is method to the mans seeming madness. It`s rumoured Marker spent the off season with Tibetan Monks searching for enlightenment, where the Grand Puba bestowed his wisdom - The value of a tournament bonus point outweighs a handful of stableford points across the weekend. </p><p>So Marker set about his limited Seeding with renewed purpose - no longer worried about protecting his handicap, he played with gusto and (somewhat dubiously) reduced it by 10%, thus earning himself a very valuable edge on the competition. As Marker sits patiently polishing his wood and kneading his balls, he knows that the trophy is within reach... all he has to do is demolish Pussy in the off course drinking and he`ll be well on the way to victory.\r\n</p>\r\n\r\n<p>\r\n<blockquote class="right">"This group is about Shankers, not family days out, or digging up some old shag!" <cite>- The Marker</cite></blockquote>\r\n</p>', '0000-00-00 00:00:00', 0, NULL, 'img/avatar/marker2015.png', '20.5', '3413300610'),
(49, 7, 'Mole', 'Scraper', 'Moley', '<p class="lead">Trev Says...</p>\r\n\r\n<p>After withdrawal from the 2017 competition and being relegated to watching the rAdelaide Tournament events unfold in his Y-fronts on the couch through the WhatsApp feed, Moley seems keen to make an impact this year. </p>\r\n\r\n<p>By outsourcing handicapping duties to the Social Golf Club and Golf Australia, Moley is now free to focus on his own game without worrying about the inevitable integrity questions and incessant banter that a win under his own stewardship would have brought. </p><p>Lifting the 2018 trophy will be a challenge for the man with the lowest altitude 200m drive on record and he`ll need to overcome his current over reliance on spectacular golfing shots to counteract the holes where he has more shots than a depressed bridesmaid at a hens party. </p><p>\r\nThe quality of this year`s field leaves him nowhere to hide and not being able practice his actual golf game as much as he`d like, Moley is looking to non conventional tactics to try and enhance his game. We`ll see another spike in Herbalife shares if his strategy of decaf green tea, nonchalant zen like swing, meditating whilst caressing dirty golf balls and performing the Haka prior to tee off pays dividends.</p>\r\n\r\n<p>\r\n<blockquote class="right">"I excel at organising golf trips, just not playing in them " <cite>- Moley </cite></blockquote>\r\n</p>', '2015-05-11 10:51:55', 0, NULL, 'img/avatar/moley2015.PNG', '24.2', '3413300028'),
(50, 7, 'Farrier', 'McKnight', 'Farrier', '<p class="lead">Trevor says...</p>\r\n\r\n<p>He`s trained horses to dominant race victories, excelled in country cricket teams and sparred shot for shot with Aaron Baddley on the junior golfing circuit - a pretty solid sporting career one might say. </p><p>Alas, the Farrier could never put his finger on it, but always felt there was something missing.... Until now! </p><p>\r\nFor a married man who has a daughter, some pundits felt he might have been over stating it when he described receiving his official Shankers 2018 Invitation as "... unequivocally the happiest day of my life!". But in a recent interview with yours truly when I was a respected journalist at Golf Quarterly, Farrier put further context to his comments "... it`s like all your life you dream of something bigger, and you`re just waiting for the day ShITOC recognises you and invites you on the tour. My chance is now, and I plan to take it by the short and curlies and give it the best shot I can." </p><p>\r\nThe man from Maldon joins the tour as the best handicapped golfer in the 2018 line up. He has confidence to spare and will surely be in contention for the best banter on tour award. Although unarguably talented, the low margin for error afforded by his handicap will be the true test for this man over the gruelling 3-day tournament. With no previous form to go by I`ll be very interested to see how his golf game handles the seedy mornings and the added pressure of Power Plays!\r\n</p>\r\n\r\n<p>\r\n<blockquote class="right">"Seriously getting stooged by you blokes. How can I be giving away 20 shots before we even tee off. Next thing you will all want to be teeing off the red markers and wearing skirts!!" <cite>- The Farrier</cite></blockquote>\r\n</p>', '2018-01-22 00:00:00', 0, NULL, 'img/avatar/farrier.png', '0.0', '3041200497');
